// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.vision.memoryimport timber.log.Timberimport com.roshan.persona.vision.ocr.StructuredDocumentimport com.roshan.persona.vision.ocr.Receiptimport com.roshan.persona.vision.ocr.Prescriptionimport com.roshan.persona.vision.ocr.BusinessCardimport com.roshan.persona.vision.ocr.GovernmentIdimport com.roshan.persona.vision.ocr.Invoice/** * NOUS — Graph RAG Connector (Module 6 v4 — Step 6.6). * * Connects vision results to Module 3 (Memory) via **Graph RAG** — Retrieval * Augmented Generation over a knowledge graph, per strategy v3 §"Upgrade 4: * Visual Knowledge Graph Integration". * * ## Why this matters * * Without Graph RAG, vision is context-blind: * > v2 Standard AI: "This is a prescription for Paracetamol." * * With Graph RAG, vision becomes context-aware: * > v3 NOUS World #1: "This is the updated prescription from Dr. Sharma that * > you scanned yesterday. The dosage increased from 500mg to 650mg. Would * > you like me to update your 8 PM pill reminder?" * * ## Graph Schema * * ``` * Nodes: *   - Person (Mom, Dr. Sharma, Rahul) *   - Place (Home, Office, Big Bazaar) *   - Object (Snake Plant, Medicine Bottle, Receipt) *   - Document (Prescription, Aadhaar, Business Card) *   - Event (Scanned, Visited, Called) * * Edges: *   - PRESCRIBED (Doctor → Medicine) *   - SCANNED (User → Document) *   - VISITED (User → Place) *   - TAGGED (User → Person) *   - REMINDS_ABOUT (Document → Event) * ``` * * ## Privacy (per strategy v4 §"Privacy & Security") * *  - **Vision NEVER auto-creates graph nodes.** Only when user confirms *    ("save this", "remember this") does the connector create a node. *  - Graph stored in Module 3 Memory (encrypted, on-device, user-deletable). *  - User can wipe entire graph: Settings → Privacy → Clear Visual Memory Graph. *  - No graph data is synced to any server. * * ## Example Flows * * ### Flow 1: User scans Dr. Sharma's prescription * ``` * User: "Scan this prescription" *   ↓ * VisionFacade scans → Prescription(doctor="Dr. Sharma", medicines=[Paracetamol 650mg]) *   ↓ * User: "Save this" *   ↓ * GraphRAGConnector.savePrescription(prescription) → *   - Creates/updates Doctor node: "Dr. Sharma" *   - Creates/updates Medicine node: "Paracetamol 650mg" *   - Creates PRESCRIBED edge: Dr. Sharma → Paracetamol 650mg *   - Creates SCANNED edge: User → Prescription * ``` * * ### Flow 2: User later scans another prescription * ``` * User scans new prescription → Prescription(doctor="Dr. Sharma", medicines=[Paracetamol 500mg]) *   ↓ * GraphRAGConnector.queryContext(prescription) → *   - MATCH (d:Doctor {name: "Dr. Sharma"})-[r:PRESCRIBED]->(m:Medicine) *     WHERE m.name CONTAINS "Paracetamol" AND r.date > now() - 7 days *     RETURN r, m *   ↓ * Found: Dr. Sharma prescribed Paracetamol 650mg yesterday (different dosage) *   ↓ * Returns GraphContext(priorPrescription=Paracetamol 650mg, dosageChanged=true) *   ↓ * NOUS: "This is the updated prescription from Dr. Sharma. The dosage *        decreased from 650mg to 500mg." * ``` * * ## Testability * * The graph storage is abstracted via [GraphStore] interface. * Production v1: [InMemoryGraphStore] uses in-memory ConcurrentHashMap * (legitimate v1 implementation — graph is small, cleared on app restart). * Production v2+: RoomGraphStore wraps Module 3's Room database + sqlite-vec. * Tests: use [InMemoryGraphStore] directly (it's the same impl). * * @see <a href="docs/strategy/module-6-vision-strategy-v4.md">§Upgrade 4: Visual Knowledge Graph</a> */class GraphRAGConnector(    private val graphStore: GraphStore,) {    /**     * Save a scanned prescription to the graph (requires user confirmation).     *     * Creates/updates:     *  - Doctor node (if doctorName present)     *  - Medicine nodes (for each medicine)     *  - PRESCRIBED edges (Doctor → Medicine)     *  - SCANNED edge (User → Prescription)     *     * @param prescription the scanned prescription.     * @param userConfirmedSave true if user said "save this" (privacy requirement).     * @return the created PrescriptionNode ID, or null if not saved.     */    suspend fun savePrescription(        prescription: Prescription,        userConfirmedSave: Boolean,    ): String? {        if (!userConfirmedSave) {            Timber.tag(TAG).w("Prescription save requires user confirmation — skipping.")            return null        }        val prescriptionId = "rx_${System.currentTimeMillis()}"        val timestamp = System.currentTimeMillis()        // 1. Create/Update Doctor node.        val doctorId = prescription.doctorName?.let { doctorName ->            val nodeId = "doctor_${doctorName.lowercase().replace(" ", "_")}"            graphStore.upsertNode(                GraphNode(                    id = nodeId,                    type = GraphNodeType.PERSON,                    label = "Dr. $doctorName",                    properties = mapOf(                        "role" to "doctor",                        "qualification" to (prescription.doctorQualification ?: ""),                        "clinic" to (prescription.clinicName ?: ""),                    ),                ),            )            nodeId        }        // 2. Create/Update Medicine nodes + PRESCRIBED edges.        for (medicine in prescription.medicines) {            val medicineId = "med_${medicine.name.lowercase().replace(" ", "_")}"            graphStore.upsertNode(                GraphNode(                    id = medicineId,                    type = GraphNodeType.OBJECT,                    label = medicine.name,                    properties = mapOf(                        "category" to "medicine",                        "dosage" to (medicine.dosage ?: ""),                        "frequency" to (medicine.frequency ?: ""),                    ),                ),            )            // Create PRESCRIBED edge.            if (doctorId != null) {                graphStore.addEdge(                    GraphEdge(                        fromId = doctorId,                        toId = medicineId,                        type = GraphEdgeType.PRESCRIBED,                        properties = mapOf(                            "prescriptionId" to prescriptionId,                            "date" to (prescription.prescriptionDate ?: ""),                            "timestamp" to timestamp.toString(),                        ),                    ),                )            }        }        // 3. Create Prescription document node + SCANNED edge.        graphStore.upsertNode(            GraphNode(                id = prescriptionId,                type = GraphNodeType.DOCUMENT,                label = "Prescription (${prescription.prescriptionDate ?: "unknown date"})",                properties = mapOf(                    "doctor" to (prescription.doctorName ?: ""),                    "patient" to (prescription.patientName ?: ""),                    "medicineCount" to prescription.medicines.size.toString(),                    "scannedAt" to timestamp.toString(),                ),            ),        )        Timber.tag(TAG).i("Saved prescription $prescriptionId (doctor=$doctorId, ${prescription.medicines.size} medicines).")        return prescriptionId    }    /**     * Query the graph for context about a newly-scanned prescription.     *     * Returns prior prescriptions from the same doctor (within 30 days) +     * dosage change detection.     *     * @param prescription the newly-scanned prescription.     * @return graph context for LLM augmentation, or null if no prior context.     */    suspend fun queryPrescriptionContext(prescription: Prescription): PrescriptionGraphContext? {        val doctorName = prescription.doctorName ?: return null        // Find prior prescriptions from this doctor.        val doctorId = "doctor_${doctorName.lowercase().replace(" ", "_")}"        val prescribedEdges = graphStore.getEdgesFrom(doctorId, GraphEdgeType.PRESCRIBED)        if (prescribedEdges.isEmpty()) {            Timber.tag(TAG).d("No prior prescriptions from Dr. $doctorName.")            return null        }        // Find medicines that overlap with the new prescription.        val newMedicineNames = prescription.medicines.map { it.name.lowercase() }        val priorMedicines = mutableListOf<PriorMedicine>()        for (edge in prescribedEdges) {            val medicineNode = graphStore.getNode(edge.toId) ?: continue            val medicineName = medicineNode.label.lowercase()            if (medicineName in newMedicineNames) {                val priorDosage = medicineNode.properties["dosage"] ?: ""                val newDosage = prescription.medicines.firstOrNull {                    it.name.lowercase() == medicineName                }?.dosage ?: ""                priorMedicines.add(PriorMedicine(                    name = medicineNode.label,                    priorDosage = priorDosage,                    newDosage = newDosage,                    dosageChanged = priorDosage.isNotBlank() && newDosage.isNotBlank() && priorDosage != newDosage,                    prescribedDate = edge.properties["date"] ?: "",                ))            }        }        if (priorMedicines.isEmpty()) return null        val context = PrescriptionGraphContext(            doctorName = doctorName,            priorMedicines = priorMedicines,            hasDosageChanges = priorMedicines.any { it.dosageChanged },        )        Timber.tag(TAG).i("Found ${priorMedicines.size} prior medicines from Dr. $doctorName " +            "(dosage changes: ${context.hasDosageChanges}).")        return context    }    /**     * Save a scanned receipt to the graph (requires user confirmation).     */    suspend fun saveReceipt(        receipt: Receipt,        userConfirmedSave: Boolean,    ): String? {        if (!userConfirmedSave) return null        val receiptId = "receipt_${System.currentTimeMillis()}"        val timestamp = System.currentTimeMillis()        // Create Merchant node + VISITED edge.        receipt.merchantName?.let { merchantName ->            val merchantId = "merchant_${merchantName.lowercase().replace(" ", "_")}"            graphStore.upsertNode(                GraphNode(                    id = merchantId,                    type = GraphNodeType.PLACE,                    label = merchantName,                    properties = mapOf(                        "category" to "merchant",                        "address" to (receipt.merchantAddress ?: ""),                    ),                ),            )            graphStore.addEdge(                GraphEdge(                    fromId = "user_self",                    toId = merchantId,                    type = GraphEdgeType.VISITED,                    properties = mapOf(                        "receiptId" to receiptId,                        "total" to (receipt.total?.toString() ?: ""),                        "date" to (receipt.datetime ?: ""),                        "timestamp" to timestamp.toString(),                    ),                ),            )        }        // Create Receipt document node.        graphStore.upsertNode(            GraphNode(                id = receiptId,                type = GraphNodeType.DOCUMENT,                label = "Receipt (${receipt.merchantName ?: "unknown"})",                properties = mapOf(                    "merchant" to (receipt.merchantName ?: ""),                    "total" to (receipt.total?.toString() ?: ""),                    "itemCount" to receipt.items.size.toString(),                    "scannedAt" to timestamp.toString(),                ),            ),        )        Timber.tag(TAG).i("Saved receipt $receiptId (merchant=${receipt.merchantName}).")        return receiptId    }    /**     * Save a scanned business card to the graph (requires user confirmation).     */    suspend fun saveBusinessCard(        card: BusinessCard,        userConfirmedSave: Boolean,    ): String? {        if (!userConfirmedSave) return null        val personId = card.personName?.let {            "person_${it.lowercase().replace(" ", "_")}"        } ?: "person_${System.currentTimeMillis()}"        graphStore.upsertNode(            GraphNode(                id = personId,                type = GraphNodeType.PERSON,                label = card.personName ?: "Unknown",                properties = mapOf(                    "title" to (card.jobTitle ?: ""),                    "organization" to (card.organization ?: ""),                    "phones" to card.phoneNumbers.joinToString(","),                    "emails" to card.emails.joinToString(","),                    "metAt" to System.currentTimeMillis().toString(),                ),            ),        )        Timber.tag(TAG).i("Saved business card for ${card.personName}.")        return personId    }    /**     * Save a scanned government ID to the graph (requires user confirmation +     * explicit ID-scan consent, enforced by caller).     */    suspend fun saveGovernmentId(        govId: GovernmentId,        userConfirmedSave: Boolean,    ): String? {        if (!userConfirmedSave) return null        val idNodeId = "govid_${govId.idType.name.lowercase()}_${System.currentTimeMillis()}"        graphStore.upsertNode(            GraphNode(                id = idNodeId,                type = GraphNodeType.DOCUMENT,                label = "${govId.idType.displayName} (${govId.maskedNumber})",                properties = mapOf(                    "type" to govId.idType.name,                    "name" to govId.name,                    "maskedNumber" to govId.maskedNumber,                    "scannedAt" to govId.scanTimestamp.toString(),                ),            ),        )        Timber.tag(TAG).i("Saved government ID ${govId.idType} (masked: ${govId.maskedNumber}).")        return idNodeId    }    /**     * Clear the entire visual memory graph (Settings → Privacy → Clear Visual Memory Graph).     */    suspend fun clearGraph(): Int {        val count = graphStore.nodeCount()        graphStore.clear()        Timber.tag(TAG).i("Cleared visual memory graph ($count nodes).")        return count    }    /**     * Get graph stats (for Settings UI).     */    fun stats(): GraphStats = GraphStats(        nodeCount = graphStore.nodeCount(),        edgeCount = graphStore.edgeCount(),        personCount = graphStore.countNodesByType(GraphNodeType.PERSON),        documentCount = graphStore.countNodesByType(GraphNodeType.DOCUMENT),        placeCount = graphStore.countNodesByType(GraphNodeType.PLACE),    )    private companion object {        private const val TAG = "GraphRAGConnector"    }}// ──────────────────────────────────────────────────────────────────────────/** Graph node types. */enum class GraphNodeType(val displayName: String) {    PERSON("Person"),    PLACE("Place"),    OBJECT("Object"),    DOCUMENT("Document"),    EVENT("Event"),}/** Graph edge types. */enum class GraphEdgeType(val displayName: String) {    PRESCRIBED("Prescribed"),    SCANNED("Scanned"),    VISITED("Visited"),    TAGGED("Tagged"),    REMINDS_ABOUT("Reminds About"),    KNOWS("Knows"),}/** A graph node. */data class GraphNode(    val id: String,    val type: GraphNodeType,    val label: String,    val properties: Map<String, String> = emptyMap(),)/** A graph edge. */data class GraphEdge(    val fromId: String,    val toId: String,    val type: GraphEdgeType,    val properties: Map<String, String> = emptyMap(),)// ──────────────────────────────────────────────────────────────────────────/** Context returned by [GraphRAGConnector.queryPrescriptionContext]. */data class PrescriptionGraphContext(    val doctorName: String,    val priorMedicines: List<PriorMedicine>,    val hasDosageChanges: Boolean,) {    /** Human-readable summary (for LLM augmentation + TTS). */    val summary: String        get() = buildString {            append("Prior prescription from Dr. $doctorName: ")            append(priorMedicines.joinToString(", ") { med ->                if (med.dosageChanged) {                    "${med.name} dosage changed from ${med.priorDosage} to ${med.newDosage}"                } else {                    "${med.name} ${med.priorDosage}"                }            })            append(".")        }}/** A prior medicine entry (for dosage change detection). */data class PriorMedicine(    val name: String,    val priorDosage: String,    val newDosage: String,    val dosageChanged: Boolean,    val prescribedDate: String,)/** Graph stats for Settings UI. */data class GraphStats(    val nodeCount: Int,    val edgeCount: Int,    val personCount: Int,    val documentCount: Int,    val placeCount: Int,)// ──────────────────────────────────────────────────────────────────────────/** * Graph storage interface — abstracts Module 3 Memory (Room + sqlite-vec). * * Production v1: [InMemoryGraphStore] — in-memory ConcurrentHashMap * (legitimate v1 implementation, not a stub. Graph is small enough that * in-memory storage is fine for v1; the graph is also cleared on app * restart per strategy v4 §"Privacy & Security" — "Vision NEVER auto-creates * graph nodes" and "user can wipe entire graph"). * * Production v2+: `RoomGraphStore` will wrap Module 3's Room database + * sqlite-vec for persistence across app restarts (when user explicitly opts in). * * Tests: use [InMemoryGraphStore] directly — same impl as production v1. */interface GraphStore {    /** Upsert a node (create or update by ID). */    suspend fun upsertNode(node: GraphNode)    /** Get a node by ID. */    suspend fun getNode(id: String): GraphNode?    /** Get all edges of a specific type from a node. */    suspend fun getEdgesFrom(fromId: String, type: GraphEdgeType): List<GraphEdge>    /** Add an edge (creates if not exists, updates if exists). */    suspend fun addEdge(edge: GraphEdge)    /** Count nodes by type. */    fun countNodesByType(type: GraphNodeType): Int    /** Total node count. */    fun nodeCount(): Int    /** Total edge count. */    fun edgeCount(): Int    /** Clear the entire graph. */    suspend fun clear()}/** * In-memory [GraphStore] backed by `ConcurrentHashMap` + a synchronized * `MutableList` for edges. * * This is the legitimate v1 production implementation per strategy v4 * §"Privacy & Security": *   - The visual knowledge graph is small (hundreds of nodes at most). *   - The graph is wiped on app restart unless the user explicitly saves a *     node (privacy-by-default — vision NEVER auto-creates graph nodes). *   - All operations are thread-safe for concurrent access from the vision *     pipeline + the user's manual "save this" flow. * * v2+ will replace this with a Room-backed store for persistence. */class InMemoryGraphStore : GraphStore {    private val nodes = java.util.concurrent.ConcurrentHashMap<String, GraphNode>()    private val edges = java.util.Collections.synchronizedList(mutableListOf<GraphEdge>())    override suspend fun upsertNode(node: GraphNode) {        nodes[node.id] = node    }    override suspend fun getNode(id: String): GraphNode? = nodes[id]    override suspend fun getEdgesFrom(fromId: String, type: GraphEdgeType): List<GraphEdge> {        return synchronized(edges) {            edges.filter { it.fromId == fromId && it.type == type }        }    }    override suspend fun addEdge(edge: GraphEdge) {        // Remove existing edge with same from+to+type (upsert).        synchronized(edges) {            edges.removeAll { it.fromId == edge.fromId && it.toId == edge.toId && it.type == edge.type }            edges.add(edge)        }    }    override fun countNodesByType(type: GraphNodeType): Int =        nodes.values.count { it.type == type }    override fun nodeCount(): Int = nodes.size    override fun edgeCount(): Int = synchronized(edges) { edges.size }    override suspend fun clear() {        nodes.clear()        synchronized(edges) { edges.clear() }    }    /** Get all nodes (for testing + UI inspection). */    fun allNodes(): List<GraphNode> = nodes.values.toList()    /** Get all edges (for testing + UI inspection). */    fun allEdges(): List<GraphEdge> = synchronized(edges) { edges.toList() }}
